function _pmmOrderedFavoriteDragIds(props, ids) {
  const selected = new Set(ids);
  const mixed = props.groupedData?.mixed;
  const visible = Array.isArray(mixed) && mixed.length
    ? mixed.flatMap(node => node.type === 'category' ? node.items : [node.item])
    : props.prompts;
  return visible.filter(item => item && selected.has(item.id)).map(item => item.id);
}

