      targetSectionId: String(intent.targetSectionId || ''),
      targetPosition: intent.targetPosition === 'before' ? 'before' : 'after',
      targetGroupTitle: String(intent.targetGroupTitle || ''),
      createGroup: intent.createGroup === true,
