      if (event.pointerId != null && endEvent.pointerId != null && event.pointerId !== endEvent.pointerId) return;
      root.classList.remove('pmm-floating-dragging');
      pmmRuntimeResource(dragDocument).removeEventListener('pointermove', move, true);
      pmmRuntimeResource(dragDocument).removeEventListener('pointerup', end, true);
      pmmRuntimeResource(dragDocument).removeEventListener('pointercancel', cancel, true);
      pmmRuntimeResource(dragDocument).removeEventListener('touchmove', move, true);
      pmmRuntimeResource(dragDocument).removeEventListener('touchend', end, true);
      pmmRuntimeResource(dragDocument).removeEventListener('touchcancel', cancel, true);
